True from collections import Counter


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    lines = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != background:
            lines.append(("row", r))
    for c in range(w):
        values = [grid[r][c] for r in range(h)]
        if len(set(values)) == 1 and values[0] != background:
            lines.append(("col", c))
    for kind, i in lines:
        if kind == "row":
            out[i] = [2] * w
        else:
            for r in range(h):
                out[r][i] = 2
    return out
